mapper.select:
SELECT c.class_code AS classCode, c.operator_code AS operatorCode, c.category_code AS categoryCode, cat.parents_category AS parentCategoryCode, cat.name as categoryName, c.name as name, c.price, c.desired_price AS desiredPrice, c.zipcode, c.address, c.old_address AS oldAddress, c.address2, c.ingredients_include AS ingredientsInclude, c.status, c.review_sum AS reviewSum, c.star_rating_avg AS starRatingAvg, c.views_cnt AS viewsCnt, c.single_introduce AS singleIntroduce, c.introduce, c.finish_introduce AS finishIntroduce, c.lat, c.lng, c.approval_status AS approvalStatus, c.approval_memo AS approvalMemo, c.write_date AS writeDate, c.register_step AS registerStep,
/* 대표 이미지 (SORT_ORDER = 1) */ (SELECT ci.image FROM CLASS_IMG ci WHERE ci.class_code = c.class_code AND ci.type = '대표' AND ci.sort_order = 1 AND ROWNUM = 1) AS mainImage,
/* 스케줄 날짜 목록 (YYYY-MM-DD 형태로 변환하여 쉼표로 연결) */ (SELECT LISTAGG(TO_CHAR(s.class_date, 'YYYY-MM-DD'), ',') WITHIN GROUP (ORDER BY s.class_date) FROM class_repeat_rule crr JOIN schedule s ON s.repeat_rule_code = crr.repeat_rule_code WHERE crr.class_code = c.class_code) AS classDate,
/* 스케줄 시작 시간 목록 (HH24:MI 형태) */ (SELECT LISTAGG(s.start_time, ',') WITHIN GROUP (ORDER BY s.schedule_code) FROM class_repeat_rule crr JOIN schedule s ON s.repeat_rule_code = crr.repeat_rule_code WHERE crr.class_code = c.class_code) AS startTime
, ( 6371 * ACOS( COS( #{lat} * 3.141592653589793 / 180 ) * COS( c.lat * 3.141592653589793 / 180 ) * COS( (c.lng * 3.141592653589793 / 180) - (#{lng} * 3.141592653589793 / 180) ) + SIN( #{lat} * 3.141592653589793 / 180 ) * SIN( c.lat * 3.141592653589793 / 180 ) ) ) AS distance
FROM class c LEFT JOIN category cat ON c.category_code = cat.category_code
c.status = '모집중'
AND ( 6371 * ACOS( COS( #{lat} * 3.141592653589793 / 180 ) * COS( c.lat * 3.141592653589793 / 180 ) * COS( (c.lng * 3.141592653589793 / 180) - (#{lng} * 3.141592653589793 / 180) ) + SIN( #{lat} * 3.141592653589793 / 180 ) * SIN( c.lat * 3.141592653589793 / 180 ) ) ) <= #{distance}
AND c.address LIKE '%' || #{dong} || '%'
AND c.lat BETWEEN #{minLat} AND #{maxLat}
AND c.lng BETWEEN #{minLng} AND #{maxLng}
AND c.category_code = #{category}
AND (c.name LIKE '%' || #{keyword} || '%' OR c.address LIKE '%' || #{keyword} || '%')
ORDER BY distance ASC
ORDER BY c.class_code DESC
